/* Deterministic RNG so that a given nuclide always packs the same way and a
   screenshot is reproducible.

   This is mulberry32, a 32-bit generator that actually passes gjrand and
   PractRand. The first version of this file used a 32-bit transcription of
   xorshift128+ — which is a 64-bit algorithm, and whose shift constants (23,
   17, 26) are meaningless in 32 bits. It degenerated for some seeds, and the
   damage was invisible until the Monte-Carlo cloud started returning a 3d
   expectation value of 10.86 a0 where the closed form says 10.5. A bad RNG
   does not look broken; it looks like slightly wrong physics. */
function RNG(seed){
  var a=(seed>>>0)||0x9e3779b9;
  return function(){
    a = (a + 0x6D2B79F5)|0;
    var t = Math.imul(a ^ (a>>>15), 1|a);
    t = (t + Math.imul(t ^ (t>>>7), 61|t)) ^ t;
    return ((t ^ (t>>>14))>>>0)/4294967296;
  };
}

