  if(EXCEPT[Z]) for(i=0;i<EXCEPT[Z].length;i++){
    e=EXCEPT[Z][i];
    if(e[2]===0) delete occ[e[0]+","+e[1]]; else occ[e[0]+","+e[1]]=e[2];
  }
  var out=[];
  for(k in occ) if(occ[k]>0){ var p=k.split(","); out.push([+p[0],+p[1],occ[k]]); }
  out.sort(function(a,b){ return a[0]-b[0] || a[1]-b[1]; });
