function blockOf(Z){
  var c=configOf(Z), last=c[c.length-1];
  var e=ELEMENTS[Z-1];
  if(e[5]==="ln"||e[5]==="an") return "f";
  if(Z===2) return "s";
  var maxL=0;
  /* the block is set by the subshell being filled across the row, which for
     the main groups is the highest-l partially filled subshell */
  for(var i=0;i<c.length;i++){
    if(c[i][2]<cap(c[i][1])) maxL=Math.max(maxL,c[i][1]);
  }
  if(c.length){
    var g=ELEMENTS[Z-1][6];
    if(g>=13) return "p";
    if(g>=3 && g<=12) return "d";
    if(g===1||g===2) return "s";
  }
  return LET[maxL];
}

