function seriesKey(A){ return "4n"+(A%4); }
function bindingSEMF(Z,A){
  var N=A-Z, d;
  if(Z<1||N<0||A<1) return 0;
  var B = SEMF.aV*A - SEMF.aS*Math.pow(A,2/3)
        - SEMF.aC*Z*(Z-1)/Math.pow(A,1/3)
        - SEMF.aA*(A-2*Z)*(A-2*Z)/A;
  if(Z%2===0 && N%2===0) d= SEMF.aP/Math.sqrt(A);
  else if(Z%2===1 && N%2===1) d= -SEMF.aP/Math.sqrt(A);
  else d=0;
  return B+d;
}
/* dB/dZ = 0 gives the most tightly bound Z for a given A — the valley of
   stability. Differentiating the Coulomb and asymmetry terms:
     Z* = (aA + aC/2 A^(-1/3)) A / (2 aA + 2 aC A^(2/3) / ... )
   is easier to get right by just minimizing numerically, which is what this
   does, so there is no algebra to get wrong. */
function valleyZ(A){
  var best=1, bb=-1e9, Z;
  for(Z=1;Z<=Math.min(A,118);Z++){ var b=bindingSEMF(Z,A); if(b>bb){ bb=b; best=Z; } }
  return best;
}
function nucRadius(A, r0){ return (r0||1.2e-15)*Math.pow(A,1/3); }
function isMagic(n){ return MAGIC.indexOf(n)>=0; }
function shellFill(n){
  /* which shell-model levels are filled by n nucleons, and how far into the
     level in progress */
  var out=[], i, prev=0;
  for(i=0;i<SHELLS.length;i++){
    var s=SHELLS[i], filled=Math.max(0, Math.min(s[1], n-prev));
    if(filled>0) out.push({name:s[0], cap:s[1], in:filled, cum:s[2]});
    prev=s[2];
    if(prev>=n) break;
  }
  return out;
}

/* ----------------------------------------------------------------------------
   PART 5 — SAMPLING |psi|^2
   The electron cloud is not a picture of an orbital, it is a set of points
   drawn from the probability density. Radially by inverse-transform sampling
   of P(r) = r^2 R_nl(r)^2 (which is exactly normalized); angularly by
   rejection against |Y_lm^real(theta,phi)|^2. Nothing is stylised: the nodes
   and lobes are gaps in the sample because the density is zero there.
   ---------------------------------------------------------------------------- */
var RCACHE = {};
function radialCDF(n, l, Z){
  var key=n+"_"+l+"_"+Z.toFixed(4);
  if(RCACHE[key]) return RCACHE[key];
  /* Midpoint rule, not the right-hand Riemann sum this started as. The sum
     was biased: the median of the 1s state came back at the radius holding
     49.71% of the probability instead of 50.00%, which is small but it is a
     systematic error in every sampled point, and the cross-check against
     scipy.integrate.quad is what caught it. */
  var rmax = 3.2*n*n/Z + 18/Z, M=3000, dr=rmax/M;
  var cdf=new Float64Array(M+1), i, p, tot=0;
  cdf[0]=0;
  for(i=1;i<=M;i++){
    p=QM.hydrogenP(n,l,(i-0.5)*dr,Z);
    tot += p*dr; cdf[i]=tot;
  }
  for(i=0;i<=M;i++) cdf[i]/=tot;
  var o={cdf:cdf, dr:dr, M:M, rmax:rmax, mass:tot};
  RCACHE[key]=o; return o;
}
function sampleR(c, u){
  var lo=0, hi=c.M, mid;
  while(hi-lo>1){ mid=(lo+hi)>>1; if(c.cdf[mid]<u) lo=mid; else hi=mid; }
  var d=c.cdf[hi]-c.cdf[lo], f=d>0?(u-c.cdf[lo])/d:0;
  return (lo+f)*c.dr;
}
var YMAXC = {};
function ymax2(l,m){
  var key=l+"_"+m;
  if(YMAXC[key]!=null) return YMAXC[key];
  var best=0, i, j, t, p, v;
  for(i=0;i<=360;i++){ t=i*Math.PI/360;
    for(j=0;j<144;j++){ p=j*Math.PI/72; v=QM.YlmReal(l,m,t,p); v=v*v; if(v>best) best=v; } }
  YMAXC[key]=best*1.03; return YMAXC[key];
}
/* One point drawn from |psi_nlm|^2. Returns [x,y,z] in Bohr radii and the
   SIGN of psi, so lobes can be colored by phase. */
function samplePoint(n,l,m,Z,rnd,out){
  var c=radialCDF(n,l,Z), r=sampleR(c, rnd()), mx=ymax2(l,m), t, p, y, tries=0;
  do{
    t=Math.acos(2*rnd()-1); p=2*Math.PI*rnd();
    y=QM.YlmReal(l,m,t,p);
    if(++tries>400) break;
  } while(y*y < rnd()*mx);
  var st=Math.sin(t);
  out[0]=r*st*Math.cos(p); out[1]=r*st*Math.sin(p); out[2]=r*Math.cos(t);
  out[3]=(y*QM.hydrogenR(n,l,r,Z))<0?-1:1;
  return out;
}
/* The point cloud. `spec` is a list of {n,l,m,Z,w} with w the number of
   electrons, so a filled subshell contributes 2(2l+1) points-worth and the
   whole atom's density is drawn in proportion. */
function buildCloud(spec, count, seed){
  var rnd=RNG(seed||1), tot=0, i, k;
  for(i=0;i<spec.length;i++) tot+=spec[i].w;
  if(tot<=0) return {xyz:new Float32Array(0), sgn:new Int8Array(0), lab:[], n:0};
  var xyz=new Float32Array(count*3), sgn=new Int8Array(count), lab=new Int16Array(count);
  var tmp=[0,0,0,1], made=0, a0=QM.C.a0;
  for(i=0;i<spec.length;i++){
    var m=(i===spec.length-1) ? (count-made) : Math.round(count*spec[i].w/tot);
    for(k=0;k<m && made<count;k++){
      samplePoint(spec[i].n, spec[i].l, spec[i].m, spec[i].Z, rnd, tmp);
      xyz[made*3  ]=tmp[0]*a0;
      xyz[made*3+1]=tmp[1]*a0;
      xyz[made*3+2]=tmp[2]*a0;
      sgn[made]=tmp[3]; lab[made]=i; made++;
    }
  }
  return {xyz:xyz, sgn:sgn, lab:lab, n:made};
}
/* Radius containing a given fraction of the radial probability. Derived from
   the same normalized P(r), so the atom's drawn size is a property of the
   wavefunction rather than a look-up. */
function rQuantile(n,l,Z,q){
  var c=radialCDF(n,l,Z);
  return sampleR(c,q)*QM.C.a0;
}

/* ----------------------------------------------------------------------------
   PART 6 — NUCLEUS
   A nucleons dropped into a sphere of radius R = r0 A^(1/3) and relaxed with
   a soft repulsion until they stop overlapping. Deterministic: a given
   nuclide always packs the same way.
   ---------------------------------------------------------------------------- */
var PACKC={};
function packNucleus(Z,N){
  var key=Z+"_"+N;
  if(PACKC[key]) return PACKC[key];
  var A=Z+N, rnd=RNG(Z*4096+N+7), R=nucRadius(A), a=1.03e-15, i, j, it;
  if(A===1){ var one={pos:new Float64Array([0,0,0]), kind:new Int8Array([Z?1:0]), A:1, R:R, a:0.84e-15};
             PACKC[key]=one; return one; }
  var lim=Math.max(1e-16, R-a*0.55);
  var pos=new Float64Array(A*3);
  for(i=0;i<A;i++){
    var x,y,z,d2;
    do{ x=2*rnd()-1; y=2*rnd()-1; z=2*rnd()-1; d2=x*x+y*y+z*z; }while(d2>1);
    pos[i*3]=x*lim; pos[i*3+1]=y*lim; pos[i*3+2]=z*lim;
  }
  var minD=1.85e-15;                       /* center-to-center spacing, ~2 x r0 */
  for(it=0; it<170; it++){
    for(i=0;i<A;i++) for(j=i+1;j<A;j++){
      var dx=pos[j*3]-pos[i*3], dy=pos[j*3+1]-pos[i*3+1], dz=pos[j*3+2]-pos[i*3+2];
      var d=Math.sqrt(dx*dx+dy*dy+dz*dz)||1e-18;
      if(d<minD){
        var push=0.5*(minD-d)/d*0.55;
        pos[i*3]-=dx*push; pos[i*3+1]-=dy*push; pos[i*3+2]-=dz*push;
        pos[j*3]+=dx*push; pos[j*3+1]+=dy*push; pos[j*3+2]+=dz*push;
      }
    }
    for(i=0;i<A;i++){                      /* keep everything inside the surface */
      var px=pos[i*3], py=pos[i*3+1], pz=pos[i*3+2], rr=Math.sqrt(px*px+py*py+pz*pz);
      if(rr>lim){ var s=lim/rr; pos[i*3]=px*s; pos[i*3+1]=py*s; pos[i*3+2]=pz*s; }
    }
  }
  var kind=new Int8Array(A), idx=[];
  for(i=0;i<A;i++) idx.push(i);
  for(i=A-1;i>0;i--){ j=Math.floor(rnd()*(i+1)); var t=idx[i]; idx[i]=idx[j]; idx[j]=t; }
  for(i=0;i<Z;i++) kind[idx[i]]=1;         /* 1 = proton, 0 = neutron */
  var out={pos:pos, kind:kind, A:A, R:R, a:a};
  PACKC[key]=out; return out;
}

