var FRONTIER = [
[["fusion","climate"],"Its heavy forms, deuterium and tritium, fuel fusion experiments; on April 7, 2025, the National Ignition Facility released a record 8.6 megajoules, about four times the laser energy on target.","At what pressure does solid hydrogen become a metal? Experiments have disagreed for years, and a confirmed measurement would test our theories of matter.","https://annual.llnl.gov/fy-2025/national-ignition-facility-2025"],
[["quantum","superconductors"],"Liquid helium chills the superconducting magnets in MRI scanners and fusion machines, and helium-3 and helium-4 mixtures cool quantum chips to about a hundredth of a degree above absolute zero.","Helium-3 is extremely scarce; can quantum computers and sensors be cooled without it, or can new sources keep up with demand?",""],
[["batteries","fusion"],"Lithium-ion batteries run phones, electric cars, and grid storage, and fusion power plant designs plan lithium blankets that absorb neutrons and breed tritium fuel, which barely exists in nature.","Can lithium metal anodes in solid-state batteries stop growing needle-like dendrites that pierce the electrolyte and short-circuit the cell?",""],
[["space","fusion"],"The James Webb Space Telescope's 18 mirror segments are beryllium, which stays stiff in deep-space cold; some fusion blanket designs use beryllium to multiply neutrons for breeding tritium.","How does beryllium hold up under years of neutron bombardment in a fusion blanket, as helium and tritium build up inside it?",""],
[["medicine","fusion"],"Boron-10 captures neutrons and splits, the basis of boron neutron capture therapy, approved in Japan in 2020 for some head and neck cancers; TAE Technologies studies proton-boron fusion.","Proton-boron fusion makes few neutrons but needs far hotter plasma than deuterium-tritium fusion; can any machine reach and hold those conditions?","https://stella-pharma.co.jp/en/wp/wp-content/uploads/2021/05/Press-release_Steboronine-approvalENG.pdf"],
[["quantum","superconductors"],"Diamond hosts atom-sized defects used as quantum sensors, and two sheets of graphene twisted by about 1.1 degrees become a superconductor, a 2018 discovery that launched the field of twisted materials.","Why does magic-angle twisted graphene superconduct, and is its mechanism related to the one in copper-oxide superconductors?","https://doi.org/10.1038/nature26160"],
[["quantum","climate"],"A nitrogen atom beside a gap in diamond makes a room-temperature quantum sensor of tiny magnetic fields, and making ammonia fertilizer from air's nitrogen uses about 1 to 2 percent of world energy.","Can nitrogen from air be turned into ammonia with renewable electricity at room temperature, instead of the hot, high-pressure Haber-Bosch process?","https://www.iea.org/reports/ammonia-technology-roadmap"],
[["space"],"NASA's MOXIE experiment on the Perseverance rover made 122 grams of oxygen from the carbon dioxide in Mars' air between 2021 and 2023, a test for future rocket fuel and breathing supplies.","Can oxygen be pulled from lunar soil or Martian air at the tonnes-per-year scale that crews and return rockets would need?","https://www.nasa.gov/missions/mars-2020-perseverance/perseverance-rover/nasas-oxygen-generating-experiment-moxie-completes-mars-mission/"],
[["medicine","chips"],"Fluorine-18 is the most widely used tracer in PET scans, and fluorine-containing gases etch the nanometer-scale patterns inside computer chips.","How can PFAS forever chemicals, held together by extremely strong carbon-fluorine bonds, be destroyed cheaply in water and soil?",""],
[["chips","quantum"],"Neon is the main gas in the deep-ultraviolet lasers that pattern most chip layers; in 2022 the war in Ukraine halted two companies that supplied roughly half the world's chip-grade neon.","Can single electrons floating on frozen neon become long-lived qubits? Argonne-led teams have reported coherence near 0.1 milliseconds and want far longer.","https://www.usitc.gov/publications/332/executive_briefings/ebot_decarlo_goodman_ukraine_neon_and_semiconductors.pdf"],
[["batteries"],"Sodium-ion batteries avoid scarce lithium; CATL's Naxtra cells store up to 175 watt-hours per kilogram, and in February 2026 CATL and Changan unveiled what they call the first mass-produced sodium-ion passenger car.","Sodium ions are larger than lithium ions and fit poorly in graphite; can new electrodes give sodium cells lithium-like energy density?","https://cnevpost.com/2026/02/05/catl-sodium-batteries-begin-deployment-in-production-passenger-vehicles/"],
[["clocks","batteries"],"In NIST's aluminum ion clock, which set an accuracy record in 2025, a partner magnesium ion cools the aluminum ion and reads out its state, because aluminum is hard to control with lasers.","Magnesium ions carry two charges and crawl through solids; can cathode materials be found that make rechargeable magnesium batteries work well?","https://www.nist.gov/news-events/news/2025/07/nist-ion-clock-sets-new-record-most-accurate-clock-world"],
[["clocks","quantum"],"A single aluminum ion is the heart of NIST's quantum logic clock, with an uncertainty of 5.5 parts in 10 quintillion (2025), and thin aluminum films form the junctions in most superconducting qubits.","Tiny defects called two-level systems in aluminum oxide junctions drain energy from superconducting qubits; where exactly are they, and how can they be removed?","https://www.nist.gov/news-events/news/2025/07/nist-ion-clock-sets-new-record-most-accurate-clock-world"],
[["chips","solar","quantum"],"TSMC began volume production of 2-nanometer-class silicon chips in late 2025, and in July 2026 LONGi reported a certified 35.5 percent efficient perovskite-on-silicon tandem solar cell.","Can spin qubits in purified silicon-28 be made in ordinary chip factories and wired up by the millions without losing their quantum states?","https://www.pv-magazine.com/2026/07/15/longi-sets-new-world-record-with-35-5-efficient-perovskite-silicon-tandem-cell/"],
[["batteries","quantum"],"Lithium iron phosphate (LFP) is a leading battery cathode for electric cars and grid storage, and single phosphorus atoms placed precisely in silicon are being developed as qubits.","Phosphate rock for fertilizer is finite and found in few countries; can phosphorus be recovered economically from wastewater and manure?",""],
[["batteries","superconductors"],"Toyota and Idemitsu aim to launch cars with all-solid-state batteries using sulfide electrolytes in 2027-28, and hydrogen sulfide squeezed to extreme pressure superconducted at 203 kelvin in 2015.","In lithium-sulfur batteries, dissolved sulfur compounds shuttle between the electrodes and destroy capacity; how can this polysulfide shuttle be stopped?","https://global.toyota/en/newsroom/corporate/39865919.html"],
[["solar","chips"],"Chlorine compounds such as trichlorosilane purify the silicon in solar panels and chips, and chlorine disinfects drinking water for billions of people.","The chlor-alkali process that makes chlorine uses huge amounts of electricity; can it run efficiently on fluctuating solar and wind power?",""],
[["chips"],"Argon fluoride lasers at 193 nanometers still print most layers of computer chips, and the DUNE neutrino experiment in South Dakota will fill its giant detectors with liquid argon.","Can liquid-argon detectors like DarkSide-20k find dark matter, and can enough argon be drawn from underground wells that lack radioactive argon-39?",""],
[["batteries","quantum"],"Potassium-ion batteries are being developed as a cheaper alternative to lithium, and ultracold potassium-40 atoms let physicists simulate how electrons behave inside materials.","Potassium ions are large and make electrodes swell; can anodes survive thousands of charge cycles without cracking apart?",""],
[["clocks","quantum"],"A liquid-nitrogen-cooled calcium ion clock in Wuhan, China, reached an uncertainty of 4.4 parts in 10 quintillion in 2026, and trapped calcium ions serve as qubits in several quantum computers.","Calcium-48 beams created elements 114 to 118 but cannot reach further with available targets; which heavier beams can make elements 119 and 120?","https://doi.org/10.1103/vngc-c1xv"],
[["chips","superconductors"],"Scandium aluminum nitride is used in radio-frequency filters and studied for chip memory; a 2025 preprint claimed room-temperature superconductivity in a lanthanum-scandium hydride at crushing pressure, so far unconfirmed.","Can scandium, now costly and made in small amounts, be recovered cheaply from mining waste or the aluminum-refinery residue called red mud?","https://arxiv.org/abs/2510.01273"],
[[],"In 2024 Berkeley Lab fired a titanium-50 beam at plutonium for 22 days and made two atoms of livermorium, a test of the route it plans to use to create element 120.","Can titanium metal be made without the slow, energy-hungry Kroll process, so it becomes cheap enough for everyday cars and buildings?","https://newscenter.lbl.gov/2024/07/23/a-new-way-to-make-element-116-opens-the-door-to-heavier-atoms/"],
[["batteries"],"Vanadium flow batteries store grid energy for many hours in tanks of liquid, and RIKEN in Japan has fired vanadium-51 beams at curium in its search for element 119.","Can vanadium flow batteries become cheap enough, for example by leasing and recycling the electrolyte, to compete with lithium for long-duration storage?","https://indico.gsi.de/event/23727/contributions/95308/attachments/54987/83923/TASCA26_abstract_Morimoto_v3.pdf"],
[[],"Chromium keeps stainless steel from rusting, and layered chromium compounds such as CrSBr are studied as atom-thin magnets for future low-power spin electronics.","How can toxic hexavalent chromium in groundwater near old industrial sites be detected and cleaned up cheaply?",""],
[["batteries"],"GM and LG Energy Solution plan to produce lithium manganese-rich cells for electric trucks starting in 2028, using more manganese and less costly cobalt.","Manganese-rich cathodes slowly lose voltage as atoms migrate during cycling; can this voltage fade be stopped for good?","https://news.gm.com/home.detail.html/Pages/news/us/en/2025/may/0513-GM-LG-Energy-Solution-pioneer-LMR-battery-cell-technology.html"],
[["batteries","climate","superconductors"],"Form Energy is building iron-air batteries designed to discharge for up to 100 hours, starting with a utility pilot in Minnesota; some iron compounds are high-temperature superconductors.","Can steel be made with hydrogen or electricity instead of coal at a competitive price? Steelmaking emits about 7 to 9 percent of global carbon dioxide.","https://greatriverenergy.com/what-we-do/cambridge-energy-storage-project"],
[["batteries","chips"],"Cobalt stabilizes many electric-car battery cathodes and fills tiny chip contacts; the Democratic Republic of the Congo, the top producer, halted exports in February 2025 and switched to quotas that October.","Can high-energy battery cathodes drop cobalt completely without losing stability and lifetime?","https://www.iea.org/policies/29138-drc-arecoms-decision-no-0042025-cobalt-quota-system"],
[["batteries","superconductors"],"High-nickel cathodes give electric cars long range, and in 2025 thin films of a layered nickel oxide were shown to superconduct above 40 kelvin at normal pressure; a later study pushed the onset to about 63 kelvin.","Why do these layered nickel oxides superconduct, and can films at normal pressure reach the 80-plus kelvin seen when the crystals are squeezed?","https://arxiv.org/abs/2512.04708"],
[["chips","superconductors"],"Copper still carries the signals in chips, but its resistance climbs in the narrowest wires, so makers add ruthenium and cobalt liners; copper oxides also form tapes for superconducting fusion magnets.","What makes copper-oxide cuprate superconductors work above 77 kelvin? The mechanism has been debated since their discovery in 1986.",""],
[["batteries"],"Zinc batteries with water-based electrolytes are nonflammable and use a cheap, abundant metal, so companies are testing them for grid energy storage.","Zinc grows sharp dendrites and corrodes during charging; can rechargeable zinc anodes last thousands of cycles?",""],
[["chips","solar","space"],"Gallium nitride chips power fast chargers and 5G radios; China makes about 99 percent of the world's raw gallium and has restricted its export since 2023.","Can gallium oxide, whose very wide bandgap suits high-voltage power chips, overcome its poor ability to carry heat away?","https://pubs.usgs.gov/periodicals/mcs2026/mcs2026-gallium.pdf"],
[["chips","quantum","space"],"Germanium goes into fast silicon-germanium transistors, satellite solar cells, and infrared optics; China banned its export to the US in December 2024, then suspended the ban in November 2025.","Can holes in germanium quantum wells be made into large two-dimensional arrays of high-quality spin qubits?","https://fastmarkets.com/insights/china-suspends-export-prohibition-on-superhard-materials-us"],
[["solar","space"],"Gallium arsenide forms the lasers that send data through fiber-optic links and the high-efficiency multi-junction solar cells on most traditional satellites, though huge constellations are switching to cheaper silicon cells.","How can arsenic be removed cheaply from well water in Bangladesh and India, where tens of millions of people drink unsafe levels?","https://space-economy.esa.int/article/336/esa-technology-market-assessments-understanding-the-foreseen-demand-for-solar-generators-and-solar-cells"],
[["solar"],"Selenium is a key ingredient of flexible CIGS thin-film solar cells and of antimony selenide cells, researched as a cheap, stable alternative.","Can antimony selenide solar cells, built from cheap and stable elements, overcome the defects that keep their efficiency far below silicon's?",""],
[["solar","batteries"],"Bromine tunes the bandgap of the perovskite layers stacked on silicon in tandem solar cells, and it is the active material in zinc-bromine flow batteries.","Under light, mixed iodide-bromide perovskites separate into iodide-rich and bromide-rich patches; how can this halide segregation be stopped?",""],
[["space"],"Krypton is a cheaper substitute for xenon in electric Hall thrusters and fueled early Starlink satellites; krypton-81 dates ancient groundwater and glacial ice up to about 2 million years old.","Krypton thrusters are less efficient than xenon ones; can new designs close that gap for large satellite fleets?","https://www.anl.gov/phy/tracer"],
[["quantum","clocks"],"In 2025 a Harvard, MIT, and QuEra team kept an array of more than 3,000 rubidium-atom qubits running for over two hours by reloading lost atoms; rubidium clocks also fly on GPS satellites.","Can neutral-atom computers correct errors fast enough while continuously replacing lost atoms during long calculations?","https://news.harvard.edu/gazette/story/2025/09/clearing-significant-hurdle-to-quantum-computing"],
[["clocks","quantum"],"JILA's strontium lattice clock reached an uncertainty of 8.1 parts in 10 quintillion in 2024, and in 2019 strontium became the first element identified in the glow of a neutron-star merger.","Can strontium clocks be made portable and compared across continents to map height differences in Earth's gravity to the centimeter?","https://www.nist.gov/news-events/news/2024/07/worlds-most-accurate-and-precise-atomic-clock-pushes-new-frontiers-physics"],
[["superconductors","fusion","medicine"],"Rare-earth barium copper oxide tapes, often made with yttrium, form the high-temperature superconducting magnets of fusion machines like CFS's SPARC, and yttrium-90 beads treat liver cancer.","Can rare-earth barium copper oxide tape be made cheaply enough, and survive years of neutron damage inside a fusion power plant?","https://www.neimagazine.com/news/sparc-magnet-technology-validated/"],
[["batteries"],"Zirconium alloys wrap the fuel in nuclear reactors, and the garnet LLZO, a lithium lanthanum zirconium oxide, is a leading solid electrolyte for solid-state batteries.","Can new fuel claddings resist the hot zirconium-steam reaction that produced the hydrogen explosions at Fukushima in 2011?",""],
[["superconductors","quantum"],"Niobium-tin and niobium-titanium wires make the superconducting magnets of MRI scanners and ITER, and niobium cavities trap microwaves for quantum research at Fermilab's SQMS center.","The thin oxide that forms on niobium in air drains energy from superconducting qubits and cavities; can it be blocked or removed by methods that suit large-scale chip production?",""],
[["chips","medicine"],"Chipmakers are replacing tungsten with molybdenum in the tiniest wiring, using atomic-layer deposition tools launched in 2025, and molybdenum-99 supplies the technetium used in medical scans.","Can molybdenum-99 be made reliably with accelerators instead of a few aging research reactors whose outages cause shortages?","https://siliconsemiconductor.net/article/121172/Lam_Research_ushers_in_new_era_of_semiconductor_metallisation_"],
[["medicine"],"Technetium-99m, with a six-hour half-life, is used in tens of millions of medical imaging scans each year, more than any other radioactive isotope.","Technetium-99 in nuclear waste dissolves and moves easily in groundwater; what materials can lock it away for thousands of years?","https://www.oecd.org/en/publications/the-supply-of-medical-isotopes_9b326195-en/full-report/the-use-of-nuclear-medicine-diagnostics-and-tc-99m-varies-significantly-across-countries_f169821d.html"],
[["chips"],"A ruthenium-cobalt liner announced by Applied Materials in 2024 thins copper wire linings to 2 nanometers, and Intel has shown etched ruthenium wires for future chips.","Can ruthenium replace copper in the narrowest chip wires reliably and at an affordable cost?","https://ir.appliedmaterials.com/news-releases/news-release-details/applied-materials-unveils-chip-wiring-innovations-more-energy"],
[[],"Rhodium is the catalyst in car catalytic converters that breaks down smog-forming nitrogen oxides, and it is one of the rarest and most expensive metals.","Can catalytic converters work with far less rhodium, for example by spreading it as single atoms on a support?",""],
[["fusion"],"Palladium soaks up hydrogen like a sponge; in 2025 a UBC team used electrochemically loaded palladium to raise deuterium fusion rates by 15 percent, though the setup uses far more energy than it makes.","Earlier cold fusion claims using palladium were never reproduced; can careful experiments show whether loading metals with hydrogen changes fusion rates at all?","https://groups.chem.ubc.ca/cberling/thunderbird-reactor"],
[["solar"],"Solar cell contacts used about 187 million ounces of silver in 2025, but makers are cutting silver per cell, and solar silver demand is forecast to fall 19 percent in 2026.","Can copper replace silver in solar cell contacts without corroding or shortening the cells' lifetime?","https://pv-magazine-usa.com/2026/04/15/silver-demand-from-pv-industry-expected-to-drop-19-this-year/"],
[["solar"],"Cadmium telluride thin-film panels, made in the US by First Solar, are the main alternative to silicon panels, and cadmium selenide quantum dots were part of the 2023 Chemistry Nobel story.","Can cadmium-free quantum dots match the brightness and color purity of cadmium-based ones in displays?",""],
[["solar","quantum","chips"],"Indium tin oxide forms the clear electrodes on screens and many solar cells; Microsoft's 2025 Majorana 1 chip uses indium arsenide, though other physicists dispute its topological qubit claim.","Can indium-free transparent conductors replace scarce indium tin oxide in solar cells and touchscreens?","https://www.sciencenews.org/article/microsoft-topological-quantum-majorana"],
[["chips","superconductors"],"Chipmaking EUV machines hit about 50,000 tin droplets a second with lasers to make 13.5-nanometer light, and niobium-tin wire forms ITER's main superconducting magnets.","ASML has run a 1,000-watt tin light source in tests; can EUV sources be pushed toward 2,000 watts while keeping tin debris off the mirrors?","https://www.asml.com/en/company/about-asml/locations/san-diego"],
[["batteries"],"Antimony hardens lead in batteries and goes into flame retardants; China, the top producer, banned exports to the US in December 2024 and suspended the ban in November 2025.","Liquid-metal batteries using antimony promised cheap grid storage; can their high operating temperature and corrosion problems be solved?","https://fastmarkets.com/insights/china-suspends-export-prohibition-on-superhard-materials-us"],
[["solar"],"Tellurium is half of cadmium telluride solar cells, and in 2023 the James Webb Space Telescope spotted tellurium made in a neutron-star merger after the gamma-ray burst GRB 230307A.","Tellurium is about as rare as platinum in Earth's crust; is there enough, mostly from copper refining, for cadmium telluride solar to grow to terawatt scale?","https://doi.org/10.1038/s41586-023-06759-1"],
[["solar","medicine","space"],"Iodine is a main ingredient of perovskite solar layers, iodine-131 treats thyroid cancer, and in 2021 ThrustMe reported the first iodine-fueled electric thruster operated in orbit.","Iodide ions drift inside perovskite solar cells under light and heat, degrading them; how can they be pinned in place?","https://doi.org/10.1038/s41586-021-04015-y"],
[["space","medicine"],"Xenon fuels the electric thrusters of NASA's Psyche spacecraft, and the LZ detector, holding tonnes of liquid xenon, reported no sign of light dark-matter particles in December 2025.","LZ has already reached the neutrino fog for light dark matter; can bigger xenon detectors like XLZD find heavier dark matter before neutrinos cloud that search too?","https://newscenter.lbl.gov/2025/12/08/lz-sets-a-worlds-best-in-the-hunt-for-galactic-dark-matter/"],
[["clocks","quantum"],"The second is defined by cesium-133, which ticks 9,192,631,770 times a second, and in 2025 Caltech trapped 6,100 cesium atoms as qubits in one array, among the largest ever built.","When the second is redefined, a step now aimed at 2030, should it rest on one optical clock element or on an average of several?","https://www.pma.caltech.edu/news/caltech-team-sets-record-with-6100-qubit-array"],
[["quantum","superconductors"],"Quantinuum's 98-qubit Helios computer, launched in November 2025, uses barium-137 ions as qubits, and barium is part of the copper-oxide superconducting tapes in fusion magnets.","Can trapped barium ions be shuttled and cooled fast enough to scale ion-trap quantum computers past a thousand qubits?","https://www.technologyreview.com/2025/11/05/1127659/a-new-ion-based-quantum-computer-makes-error-correction-simpler"],
[["superconductors","batteries"],"Lanthanum hydride, LaH10, superconducted at about 250 kelvin under roughly 170 gigapascals in 2019, and lanthanum-nickel alloys store hydrogen in nickel-metal hydride batteries.","Can a lanthanum-based hydride be designed that superconducts near room temperature without needing crushing pressures?","https://doi.org/10.1038/s41586-019-1201-8"],
[["magnets"],"Cerium, the most abundant rare earth, polishes glass and lenses, cleans car exhaust in catalytic converters, and is mixed into some neodymium magnets to lower their cost.","How much neodymium can cerium replace in permanent magnets before they become too weak for motors?",""],
[["magnets","superconductors"],"Praseodymium is blended with neodymium in electric-motor magnets, and it is part of (La,Pr)3Ni2O7, one of the squeezed nickel oxide films found in 2025 to superconduct at normal pressure.","Squeezed nickel oxide films, with or without praseodymium, superconduct at normal pressure near 40 kelvin; can better strain engineering push them toward the 80 kelvin seen under high pressure?","https://doi.org/10.1038/s41586-025-08755-z"],
[["magnets","climate"],"Neodymium-iron-boron magnets drive most electric-car motors and many wind turbines; in 2025 the US Defense Department backed MP Materials to expand domestic magnet production.","Can strong permanent magnets be made without rare earths, for example from iron nitride, for motors and turbines?","https://www.manufacturingdive.com/news/mp-materials-northlake-texas-10x-rare-earth-magnet-campus-defense-pentagon/813400/"],
[[],"Promethium has no stable isotopes; in 2024 Oak Ridge chemists made the first promethium complex in water and measured its bond length, filling a gap in the lanthanide series.","Can promethium-147 be separated efficiently enough to revive long-lasting nuclear batteries for remote sensors and spacecraft?","https://doi.org/10.1038/s41586-024-07267-6"],
[["magnets","medicine"],"Samarium-cobalt magnets keep their strength at high temperatures in jet engines; China put samarium under export licensing in April 2025, and samarium-153 eases bone cancer pain.","Can samarium-cobalt magnets be made stronger by better controlling their nanoscale cell structure during heat treatment?","https://www.hklaw.com/en/insights/publications/2025/04/china-imposes-export-controls-on-medium-and-heavy-rare-earth-materials"],
[["quantum"],"Europium ions in a crystal held a quantum state for about six hours in a 2015 experiment, making europium a candidate for quantum memories; it also makes the red light in many screens.","Can europium-doped crystals store and release single photons efficiently enough to serve as memories in long-distance quantum networks?","https://doi.org/10.1038/nature14025"],
[["medicine"],"Gadolinium contrast agents sharpen MRI scans, and Japan's Super-Kamiokande detector has added gadolinium to its water since 2020 to catch neutrinos from distant supernovae.","Small amounts of gadolinium from MRI contrast agents stay in the brain for years; does this harm health, and can safer agents replace them?","https://www.icrr.u-tokyo.ac.jp/en/news/9390/"],
[["magnets","medicine"],"Terbium keeps electric-motor magnets strong when hot, and terbium-161, a cancer radiotherapy, showed early safety in the 2025 VIOLET prostate cancer trial in Australia.","Does terbium-161's shower of short-range electrons kill tiny tumor clusters better than lutetium-177, as lab studies suggest?","https://www.petermac.org/about-us/news-and-events/news/details/incredibly-encouraging-first-results-of-terbium-prostate-cancer-therapy"],
[["magnets","climate"],"Dysprosium lets neodymium magnets in electric-car motors and wind turbines survive heat; China, which dominates supply, put it under export licensing in April 2025.","Magnets free of dysprosium already run some hybrid-car motors; can they match its heat resistance in the hottest electric-car and wind-turbine motors?","https://www.hklaw.com/en/insights/publications/2025/04/china-imposes-export-controls-on-medium-and-heavy-rare-earth-materials"],
[["medicine","magnets"],"Holmium lasers break up kidney stones, holmium-166 beads treat liver tumors, and in 2017 IBM researchers stored one bit of data in a single holmium atom.","Holmium atoms on magnesium oxide hold a magnetic bit up to about 35 kelvin; can single-atom magnets keep data stable at much warmer, more practical temperatures?","https://doi.org/10.1038/nature21371"],
[["quantum"],"Erbium-doped fiber amplifiers boost the light in internet cables at 1,550 nanometers, and single erbium ions are being developed as quantum network nodes that work at telecom wavelengths.","Can single erbium ions in silicon or crystals become reliable spin-photon qubits for a quantum internet?","https://link.springer.com/article/10.1038/s41586-023-06281-4"],
[["medicine","clocks"],"Thulium fiber lasers increasingly break up kidney and bladder stones, and physicists are building optical clocks on an inner-shell thulium transition shielded from heat.","Can thulium's shielded inner-shell transition make an optical clock nearly immune to errors from surrounding heat radiation?","https://www.ncbi.nlm.nih.gov/pmc/articles/PMC6461630/"],
[["quantum","clocks"],"In 2024 Microsoft and Atom Computing entangled 24 logical qubits built from ytterbium atoms, and ytterbium lattice clocks at NIST are among the most stable clocks ever built.","Tiny unexplained patterns in ytterbium isotope shifts could hint at a new force; are they new physics or an effect of nuclear structure?","https://azure.microsoft.com/en-us/blog/quantum/2024/11/19/microsoft-and-atom-computing-offer-a-commercial-quantum-machine-with-the-largest-number-of-entangled-logical-qubits-on-record/"],
[["medicine","clocks"],"Lutetium-177 drugs like Pluvicto treat advanced prostate cancer, and in September 2026 a Singapore team reported a lutetium ion clock with a record uncertainty of about 1 part in 10 quintillion.","Can enough lutetium-177 be made, from scarce enriched ytterbium-176 targets, to meet rising demand for cancer treatments?","https://thequantuminsider.com/2026/09/24/singapore-scientists-claim-they-built-the-worlds-most-accurate-atomic-clock/"],
[["chips"],"Hafnium oxide insulates the transistor gates in nearly all modern chips, and mixed with zirconium it becomes ferroelectric, a candidate for fast, low-power memory.","Why do hafnium-zirconium oxide films become ferroelectric at all, and how can their wake-up and fatigue problems be fixed?","https://www.oaepublish.com/pre_onlines/microstructures.2025.32"],
[["quantum","chips"],"Princeton engineers reported tantalum-on-silicon superconducting qubits in Nature in November 2025, with energy lifetimes up to 1.68 milliseconds.","Which surface oxides and interfaces on tantalum still limit superconducting qubit lifetimes, and how thin can they be made?","https://doi.org/10.1038/s41586-025-09687-4"],
[["fusion","chips"],"In February 2025 France's tungsten-walled WEST tokamak held a plasma for a record 1,337 seconds, and ITER switched its first wall from beryllium to tungsten in its 2024 plan.","How does tungsten armor crack, swell, and grow nanoscale fuzz under years of fusion plasma and neutron bombardment?","https://irfm.cea.fr/en/2025/02/west-sets-a-new-plasma-duration-record/"],
[[],"Rhenium is added to nickel superalloys in jet-engine turbine blades so they resist slow deformation at extreme heat; it is one of the rarest elements in Earth's crust.","Can turbine superalloys keep their high-temperature strength while using much less scarce rhenium?",""],
[[],"Osmium is the densest natural element, osmium tetroxide stains cells for electron microscopes, and osmium isotopes in sediments record ancient weathering and asteroid impacts.","What do osmium isotope records in ocean sediments reveal about how fast continents weathered during past climate shifts?",""],
[["climate"],"Green-hydrogen PEM electrolyzers rely on iridium oxide catalysts, yet the world produces only about 7 to 8 tonnes of iridium a year, mostly as a byproduct of platinum mining.","Can PEM electrolyzers use far less iridium, or none, while surviving acid and high voltage for years?","https://arxiv.org/html/2509.05357v1"],
[["climate","medicine"],"Platinum catalysts power hydrogen fuel cells and electrolyzers, and the platinum drug cisplatin has been used against testicular and other cancers since 1978.","Can fuel cell catalysts cut platinum use several times over without wearing out faster?","https://cancer.gov/research/progress/discovery/cisplatin"],
[["space"],"Gold coats the James Webb Space Telescope's mirrors to reflect infrared light, and a 2025 study suggested magnetar flares may have made 1 to 10 percent of our galaxy's gold and other heavy elements.","How much of the universe's gold comes from neutron-star mergers, compared with magnetar flares or rare supernovae?","https://www.simonsfoundation.org/2025/04/29/flares-from-magnetized-stars-can-forge-planets-worth-of-gold-other-heavy-elements/"],
[["clocks","space"],"NASA's Deep Space Atomic Clock, a mercury-ion clock, ran in orbit from 2019 to 2021 and was up to 10 times more stable than earlier space clocks.","How can small-scale gold mining, the largest human source of mercury pollution, recover gold without using mercury?","https://doi.org/10.1038/s41586-021-03571-7"],
[["medicine"],"Thallium-201 has long been used in heart stress scans, though technetium and PET tracers now do most of that work; thallium compounds are extremely toxic.","Relativity makes thallium favor a +1 charge; can experiments on nihonium, just below it, show whether this trend gets stronger?",""],
[["solar","medicine","batteries"],"Lead halide perovskites drive record tandem solar cells, such as LONGi's 35.5 percent cell in 2026, and lead-212 is being tested as an alpha-particle cancer therapy.","Can perovskite solar panels last 25 years outdoors while keeping their lead from leaking if they break?","https://www.pv-magazine.com/2026/07/15/longi-sets-new-world-record-with-35-5-efficient-perovskite-silicon-tandem-cell/"],
[["medicine"],"Bismuth telluride runs most thermoelectric coolers, bismuth-213 is tested in alpha-particle cancer therapy, and bismuth selenide is a topological insulator that conducts only along its surface.","Can thermoelectric materials beyond bismuth telluride turn waste heat into electricity efficiently near room temperature?",""],
[[],"Polonium-210 removes static in industrial brushes and once heated Soviet moon rovers; it is the only element whose normal solid form is a simple cubic crystal.","Polonium is so radioactive that samples heat themselves; how much of its relativity-shaped chemistry, predicted by calculations, is actually right?",""],
[["medicine"],"Astatine-211, with a 7.2-hour half-life, is in clinical trials as a targeted alpha therapy for cancer, yet no visible amount of astatine has ever been collected.","Is astatine a metal? Calculations say yes, but no one has made enough to test its basic properties directly.","https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9859440/"],
[[],"Radon gas seeping from soil is the leading cause of lung cancer among US nonsmokers, according to the EPA, and dark-matter experiments work hard to filter it out.","How can radon be removed from xenon dark-matter detectors well enough for the sensitivity next-generation experiments need?","https://www.epa.gov/radon/health-risk-radon"],
[[],"Francium has no stable isotopes, but TRIUMF in Canada traps francium atoms with lasers to measure how the weak nuclear force acts inside atoms.","Can francium's large atomic parity violation be measured precisely enough to test the Standard Model's weak force?","https://arxiv.org/abs/1312.3562"],
[["medicine"],"Radium-223 treats prostate cancer that has spread to bone, and CERN researchers study radium monofluoride molecules, whose pear-shaped nuclei could reveal broken symmetries of nature.","Could radium-containing molecules reveal an electric dipole moment that helps explain why the universe holds more matter than antimatter?","https://doi.org/10.1038/s41586-020-2299-4"],
[["medicine"],"Actinium-225 is a promising targeted alpha cancer therapy, but supply is tight; in 2025 the US DOE Isotope Program agreed for the first time to supply accelerator-made actinium-225 for a clinical trial.","How can actinium-225 be mass-produced with accelerators without contaminating it with long-lived actinium-227?","https://isotopes.gov/Groundbreaking-Cancer-Therapy-Clinical-Trial-with-Accelerator-Produced-Actinium-225"],
[["clocks"],"In October 2026 teams in Vienna and Beijing reported the first working nuclear clocks, which tick with thorium-229 nuclei held in calcium fluoride, probed by laser light near 148 nanometers.","Can a thorium-229 nuclear clock detect whether constants of nature, like the fine-structure constant, drift over time?","https://doi.org/10.1038/s41586-026-11084-4"],
[["climate"],"In 2025 Chinese scientists reported protactinium-233 in their TMSR-LF1 molten-salt reactor, showing thorium turning into uranium-233 fuel; protactinium-231 in seafloor mud tracks past ocean currents.","Did the Atlantic's overturning circulation collapse abruptly during past climate shifts, and can protactinium-thorium records show how fast?","https://sinap.cas.cn/xwzx/cmsm/202511/t20251107_8008517.html"],
[["climate"],"Many advanced reactors need high-assay low-enriched uranium (HALEU); in June 2025 Centrus delivered 900 kilograms of it to the US Department of Energy from its Ohio plant.","Can uranium be extracted cheaply from seawater, which holds about 4 billion tonnes of it?","https://www.energy.gov/node/4851599"],
[["space"],"Oak Ridge National Laboratory irradiates neptunium-237 targets in its High Flux Isotope Reactor to make plutonium-238, the heat source for NASA's deep-space power systems.","Can neptunium be separated from spent fuel and transmuted, shortening how long nuclear waste stays dangerous?","https://www.ornl.gov/news/nuclear-deep-space-travel"],
[["space"],"Plutonium-238 heat powers NASA's Perseverance rover and will power Dragonfly, a nuclear-powered rotorcraft scheduled to launch to Saturn's moon Titan in July 2028.","Plutonium metal has six solid phases, and one shrinks when heated; how do its 5f electrons cause this, and how does it age?","https://science.nasa.gov/mission/dragonfly/"],
[["space"],"Americium-241 is in household smoke detectors, and the UK's National Nuclear Laboratory is developing americium power sources, extracted from stored plutonium, for European space missions.","Can americium power sources, which need more fuel and shielding than plutonium-238 ones, be made light enough for long space missions?","https://world-nuclear-news.org/articles/nnl-to-develop-americium-powered-space-batteries"],
[["space"],"Curium-244 supplies the radiation that lets X-ray spectrometers on Mars rovers such as Curiosity read rock chemistry, and RIKEN fired vanadium beams at curium-248 targets in its search for element 119.","Which reaction will make element 119 first, vanadium on curium or titanium on berkelium, given how rarely these fusions succeed?","https://indico.gsi.de/event/23727/contributions/95308/attachments/54987/83923/TASCA26_abstract_Morimoto_v3.pdf"],
[[],"Berkelium-249 made in Oak Ridge's High Flux Isotope Reactor was the target used to discover tennessine in 2010; only tiny amounts of berkelium are produced at a time.","Does berkelium's chemistry mirror terbium's, the lanthanide above it, or do relativistic effects change its bonding and its +4 state?","https://ornl.gov/blog/ornl-reporter/international-association-approves-element-117-tennessine"],
[[],"Oak Ridge is preparing a californium-249 target for Berkeley Lab's planned attempt to make element 120 by bombarding it with titanium-50 ions.","How do californium's chemical bonds differ from those of lighter actinides as relativistic effects grow and its 5f electrons join in?","https://indico2.riken.jp/event/5355/contributions/28965/"],
[[],"In 2021 Berkeley Lab and Los Alamos chemists measured einsteinium's first bond distance using less than 250 nanograms of the element.","Could enough einsteinium ever be made to serve as a target for new superheavy elements, or to study its chemistry in bulk?","https://newscenter.lbl.gov/2021/02/03/discoveries-at-the-edge-of-the-periodic-table-first-ever-measurements-of-einsteinium/"],
[[],"In 2024 a GSI and Mainz team used lasers on fermium isotopes and found that their nuclear size grows smoothly as neutrons are added, testing models of the heaviest nuclei.","Why does fermium-258 split by spontaneous fission in under a millisecond, while nearby fermium isotopes live far longer?","https://doi.org/10.1038/s41586-024-08062-z"],
[[],"Mendelevium is made a few atoms at a time in accelerators, and chemists use it to test whether the heaviest actinides prefer a +2 or a +3 charge.","Mendelevium favors +3 in water but slips into +2 more easily than lighter actinides; would its metal be divalent like europium, as trace experiments hint, if a bulk sample were ever made?",""],
[[],"In 2025 Berkeley Lab directly identified molecules containing nobelium with its FIONA mass spectrometer, the first such measurement for any element with more than 99 protons.","Nobelium's full 5f electron shell explains much of its +2 preference, but how strongly do relativistic effects change its bonds compared with lighter actinides, as the 2025 study began to test?","https://newscenter.lbl.gov/2025/08/04/new-technique-sheds-light-on-chemistry-at-the-bottom-of-the-periodic-table/"],
[[],"In 2015 Japanese researchers measured lawrencium's ionization energy one atom at a time, feeding a debate about whether it belongs under lutetium in group 3.","Is lawrencium's outermost electron in a p orbital instead of the d orbital the table suggests, and where should it be placed?","https://doi.org/10.1038/nature14342"],
[[],"Rutherfordium, the first element after the actinides, is studied atom by atom in gas and liquid chemistry experiments to see whether it behaves like hafnium and zirconium.","Do relativistic effects make rutherfordium's compounds measurably different from those of hafnium, its lighter cousin in group 4?",""],
[[],"Dubnium, named after the Russian town of Dubna, home of the Joint Institute for Nuclear Research, is made a few atoms at a time, and its compounds are compared with those of niobium and tantalum.","How strongly do relativistic effects shift dubnium's chemistry away from niobium and tantalum, its group 5 neighbors?",""],
[[],"In 2014 an international team made seaborgium hexacarbonyl, Sg(CO)6, the first compound linking a superheavy element to carbon monoxide.","How stable are seaborgium isotopes against fission, and what do their lifetimes reveal about shell effects near 152 and 162 neutrons?","https://doi.org/10.1126/science.1255720"],
[[],"Bohrium's oxychloride was studied in 2000 using only a handful of atoms, showing it behaves like a group 7 element alongside rhenium.","Can longer-lived bohrium isotopes be found that allow deeper chemistry experiments than the handful of atoms studied so far?","https://doi.org/10.1038/35024044"],
[[],"Hassium tetroxide was first studied chemically in 2001, and hassium-270, with 108 protons and 162 neutrons, is predicted to be a doubly magic deformed nucleus.","How strong is the extra stability at 162 neutrons in hassium-270, and how does it guide the search for the island of stability?","https://www.nature.com/articles/nature00980"],
[[],"Meitnerium, named for physicist Lise Meitner, has been made only a few atoms at a time, and its chemistry has never been measured.","Would meitnerium behave like iridium, as its place in the table suggests, if an isotope long-lived enough for chemistry were found?",""],
[[],"Darmstadtium, first made at GSI in Germany in 1994, has isotopes with half-lives of seconds or less, so none of its chemistry has been studied.","Is darmstadtium a noble metal like platinum, and how would relativistic effects change its preferred charge states?","https://www.gsi.de/en/researchaccelerators/research_an_overview/new_elements/international_year_of_the_periodic_table/the_discovery_of_element_110_at_gsi"],
[[],"Roentgenium sits below gold, and calculations predict relativity strongly reshapes its electron energies, but it is made so rarely, mostly as a decay product of heavier elements, that its chemistry is still unstudied.","Would roentgenium, gold's heavier cousin, behave like gold, or would relativity make it a very different element?",""],
[[],"Copernicium atoms were shown in 2007 to stick only weakly to gold, like a volatile metal, and calculations predict it may be liquid near room temperature.","Is copernicium a volatile, nearly noble-gas-like metal, and does it really melt near room temperature as calculations predict?","https://pubmed.ncbi.nlm.nih.gov/17476264/"],
[[],"Nihonium, the first element discovered in Asia, was found in 2024 gas-chemistry experiments at GSI in Germany to be more chemically reactive than its neighbor flerovium.","How do strong relativistic effects on its single outer 7p electron make nihonium's chemistry differ from thallium's?","https://doi.org/10.3389/fchem.2024.1474820"],
[[],"Experiments at GSI reported in 2022 that flerovium is highly volatile and the least reactive member of group 14, binding to gold less than mercury does but more than radon.","Flerovium appears to be a very volatile metal, but with only a few atoms measured, how strongly does it really bond, and did stray molecules skew earlier experiments?","https://doi.org/10.3389/fchem.2022.976635"],
[[],"Moscovium became the heaviest element ever studied chemically in 2024, when a GSI-led team found it more reactive than flerovium using just a handful of atoms.","Does moscovium behave like bismuth above it, or does relativity push it toward thallium-like +1 chemistry?","https://doi.org/10.3389/fchem.2024.1474820"],
[[],"In 2024 Berkeley Lab made two livermorium atoms by hitting plutonium-244 with titanium-50 instead of the usual calcium-48, a test run for creating element 120.","Can titanium-50 beams make new elements at useful rates, given that livermorium formed only twice in 22 days of beam time?","https://newscenter.lbl.gov/2024/07/23/a-new-way-to-make-element-116-opens-the-door-to-heavier-atoms/"],
[[],"Tennessine was first made in 2010 at Dubna in Russia by hitting a berkelium target from Oak Ridge with calcium-48 ions.","Is tennessine a true halogen like iodine, or do relativistic effects make it behave more like a metal?","https://www.ornl.gov/news/tennessine-acknowledges-state-institutions-roles-elements-discovery"],
[[],"Oganesson, the heaviest known element, has been made only a handful of times and lasts under a millisecond; calculations predict it is a solid, unlike the other noble gases.","Is oganesson really a solid semiconductor at room temperature, rather than a gas, as relativistic calculations predict?","https://en.wikipedia.org/wiki/Oganesson"]
];

/* ------------------------------------------------------------ light, as a color
   The color a human sees from a set of spectral lines: each line's intensity
   through the CIE 1931 color-matching functions (the multi-lobe Gaussian fit
   of Wyman, Sloan and Shirley 2013), summed in XYZ, then to sRGB.           */
function cieXYZ(nm){
  function g(x,mu,s1,s2){ var t=(x-mu)/(x<mu?s1:s2); return Math.exp(-0.5*t*t); }
  return [1.056*g(nm,599.8,37.9,31.0)+0.362*g(nm,442.0,16.0,26.7)-0.065*g(nm,501.1,20.4,26.2),
          0.821*g(nm,568.8,46.9,40.5)+0.286*g(nm,530.9,16.3,31.1),
          1.217*g(nm,437.0,11.8,36.0)+0.681*g(nm,459.0,26.0,13.8)];
}
function linesRGB(lines){
  var X=0,Y=0,Zc=0;
  lines.forEach(function(p){ var c=cieXYZ(p[0]), w=p[1]; X+=c[0]*w; Y+=c[1]*w; Zc+=c[2]*w; });
  var r=3.2406*X-1.5372*Y-0.4986*Zc, g=-0.9689*X+1.8758*Y+0.0415*Zc, b=0.0557*X-0.2040*Y+1.0570*Zc;
  var mn=Math.min(r,g,b); if(mn<0){ r-=mn; g-=mn; b-=mn; }               /* out of gamut: desaturate toward white */
  var mx=Math.max(r,g,b)||1; r/=mx; g/=mx; b/=mx;
  function gam(v){ return v<=0.0031308?12.92*v:1.055*Math.pow(v,1/2.4)-0.055; }
  return [gam(r),gam(g),gam(b)];
}

